# WN11 CC batch 6 (10 rules): CC-000005, 000010, 000100, 000105, 000110, 000180, 000185, 000252, 000295, 000305 (drafted with Claude)
$s = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization|NoLockScreenCamera|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization|NoLockScreenSlideshow|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Printers|DisableWebPnPDownload|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Printers|DisableHTTPPrinting|1", "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer|NoWebServices|1", "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer|NoAutorun|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer|NoAutoplayfornonVolume|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR|AllowGameDVR|0", "HKLM:\SOFTWARE\Policies\Microsoft\Internet Explorer\Feeds|DisableEnclosureDownload|1", "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search|AllowIndexingEncryptedStoresOrItems|0"
foreach ($i in $s) { $p, $n, $d = $i -split "\|"; if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }; New-ItemProperty -Path $p -Name $n -Value ([int]$d) -PropertyType DWord -Force | Out-Null; "$n = " + (Get-ItemProperty -Path $p -Name $n).$n }
